//! Parsing of the report an official validator returns.
//!
//! The EN 16931 codelist/rule Schematron is executed by an external validator
//! (Mustang, or any tool that emits the same report shape). Its report names the
//! failed rule, the XPath of the element, and the assertion text — enough to
//! compare the oracle with the live rule engine without losing the rule id.
//!
//! The parser is deliberately small and dependency-free: the report is a flat
//! document generated by a tool we control, not arbitrary input.

/// One failed assertion as reported by the validator.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Failure {
    /// Rule identifier, e.g. `BR-CL-03`.
    pub code: String,
    /// First business term mentioned in the assertion text, e.g. `BT-112`.
    pub bt: Option<String>,
    /// XPath of the element the assertion was evaluated against.
    pub location: Option<String>,
    /// Assertion text without the leading code and the trailing artefact path.
    pub message: String,
}

/// The outcome of one validator run over one document.
#[derive(Clone, PartialEq, Eq, Debug)]
pub struct Report {
    /// True when the document passed every rule.
    pub valid: bool,
    /// Specification identifier the document claims.
    pub profile: Option<String>,
    /// Version of the validator that produced the report.
    pub validator_version: Option<String>,
    /// Number of assertions evaluated.
    pub fired: u32,
    /// Number of assertions that failed.
    pub failed: u32,
    /// The failed assertions.
    pub failures: Vec<Failure>,
}

impl Report {
    /// Distinct rule codes that failed, in the order they appear.
    pub fn failed_codes(&self) -> Vec<String> {
        let mut codes: Vec<String> = Vec::new();
        for failure in &self.failures {
            if !codes.contains(&failure.code) {
                codes.push(failure.code.clone());
            }
        }
        codes
    }
}

/// Why a report could not be read.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ReportError {
    /// The document has no `<summary status="...">` element.
    MissingSummary,
}

impl std::fmt::Display for ReportError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::MissingSummary => f.write_str("the report has no summary element"),
        }
    }
}

impl std::error::Error for ReportError {}

/// Parses a validator report.
pub fn parse_report(xml: &str) -> Result<Report, ReportError> {
    let status = element_body(xml, "summary")
        .and_then(|body| attribute(body, "status"))
        .ok_or(ReportError::MissingSummary)?;

    Ok(Report {
        valid: status == "valid",
        profile: element_text(xml, "profile"),
        validator_version: element_body(xml, "validator").and_then(|body| attribute(body, "version")),
        fired: element_text(xml, "fired")
            .and_then(|value| value.parse().ok())
            .unwrap_or_default(),
        failed: element_text(xml, "failed")
            .and_then(|value| value.parse().ok())
            .unwrap_or_default(),
        failures: failures(xml),
    })
}

fn failures(xml: &str) -> Vec<Failure> {
    let mut found = Vec::new();
    let mut rest = xml;
    while let Some(start) = rest.find("<error ") {
        let element = &rest[start..];
        let Some(end) = element.find("</error>") else {
            break;
        };
        let tag = &element[..end];
        let body_start = tag.find('>').map_or(tag.len(), |at| at + 1);
        let text = decode(&element[body_start..end]);

        if let Some(code) = code(&text) {
            found.push(Failure {
                bt: business_term(&text),
                location: attribute(&tag[..body_start], "location"),
                message: message(&text, &code),
                code,
            });
        }
        rest = &element[end + "</error>".len()..];
    }
    found
}

/// The rule id from `[BR-...]-...`, falling back to the `[ID BR-...]` suffix.
fn code(text: &str) -> Option<String> {
    if let Some(open) = text.find('[')
        && let Some(close) = text[open..].find(']')
    {
        let inner = &text[open + 1..open + close];
        if inner.starts_with("BR-") {
            return Some(inner.to_owned());
        }
    }
    let at = text.find("[ID ")? + "[ID ".len();
    text[at..].split(']').next().map(str::to_owned)
}

fn message(text: &str, code: &str) -> String {
    let trimmed = text.trim_start();
    let without_code = trimmed
        .strip_prefix(&format!("[{code}]"))
        .unwrap_or(trimmed)
        .trim_start_matches('-');
    without_code.split("[ID ").next().unwrap_or_default().trim().to_owned()
}

fn business_term(text: &str) -> Option<String> {
    let at = text.find("(BT-")? + "(BT-".len();
    let digits = text[at..].chars().take_while(char::is_ascii_digit).collect::<String>();
    if digits.is_empty() {
        None
    } else {
        Some(format!("BT-{digits}"))
    }
}

/// Body of the first `<tag ...>...</tag>`, with entities decoded.
fn element_text(xml: &str, tag: &str) -> Option<String> {
    let close = format!("</{tag}>");
    let start = xml.find(&format!("<{tag}>"))? + tag.len() + 2;
    let end = xml[start..].find(&close)? + start;
    Some(decode(&xml[start..end]))
}

/// The opening tag (with attributes) of the first `<tag ...>` element.
fn element_body<'a>(xml: &'a str, tag: &str) -> Option<&'a str> {
    let start = xml.find(&format!("<{tag}"))?;
    let end = xml[start..].find('>')? + start;
    Some(&xml[start..end])
}

fn attribute(element: &str, name: &str) -> Option<String> {
    let needle = format!("{name}=\"");
    let start = element.find(&needle)? + needle.len();
    let end = element[start..].find('"')? + start;
    Some(decode(&element[start..end]))
}

fn decode(value: &str) -> String {
    value
        .replace("&lt;", "<")
        .replace("&gt;", ">")
        .replace("&quot;", "\"")
        .replace("&apos;", "'")
        .replace("&amp;", "&")
}

#[cfg(test)]
mod tests {
    use super::*;

    const VALID: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<validation filename="2026-C0001.xml" datetime="2026-10-27 19:51:28">
  <xml>
    <info>
      <version>2</version>
      <profile>urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0</profile>
      <validator version="2.17.0"/>
      <rules>
        <fired>44</fired>
        <failed>0</failed>
      </rules>
    </info>
    <summary status="valid"/>
  </xml>
  <summary status="valid"/>
</validation>"#;

    const INVALID: &str = r#"<?xml version="1.0" encoding="UTF-8"?>
<validation filename="bad.xml" datetime="2026-10-27 19:59:28">
  <xml>
    <info>
      <version>2</version>
      <profile>urn:cen.eu:en16931:2017</profile>
      <validator version="2.17.0"/>
      <rules>
        <fired>43</fired>
        <failed>2</failed>
      </rules>
    </info>
    <messages>
      <error type="24" location="/*:Invoice[1]/*:LegalMonetaryTotal[1]/*:PayableAmount[1]" criterion="((. &gt; 0))">[BR-CO-25]-In case the Amount due for payment (BT-115) is positive, either the Payment due date (BT-9) or the Payment terms (BT-20) shall be present. [ID BR-CO-25] from /xslt/en16931schematron/EN16931-UBL-validation.xslt)</error>
      <error type="24" location="/*:Invoice[1]/*:TaxTotal[1]" criterion="contains(&apos; EUR &apos;)">[BR-CL-03]-currencyID MUST be coded using ISO code list 4217 alpha-3 [ID BR-CL-03] from /xslt/en16931schematron/EN16931-UBL-validation.xslt)</error>
    </messages>
    <summary status="invalid"/>
  </xml>
  <summary status="invalid"/>
</validation>"#;

    #[test]
    fn a_valid_report_is_recognised() {
        let report = parse_report(VALID).unwrap();
        assert!(report.valid);
        assert_eq!(report.fired, 44);
        assert_eq!(report.failed, 0);
        assert!(report.failures.is_empty());
        assert_eq!(report.validator_version.as_deref(), Some("2.17.0"));
        assert_eq!(
            report.profile.as_deref(),
            Some("urn:cen.eu:en16931:2017#compliant#urn:fdc:peppol.eu:2017:poacc:billing:3.0")
        );
    }

    #[test]
    fn failures_keep_their_rule_id_term_and_location() {
        let report = parse_report(INVALID).unwrap();
        assert!(!report.valid);
        assert_eq!(report.failed, 2);
        assert_eq!(report.failures.len(), 2);

        let first = &report.failures[0];
        assert_eq!(first.code, "BR-CO-25");
        assert_eq!(first.bt.as_deref(), Some("BT-115"));
        assert!(first.message.starts_with("In case the Amount due"), "{}", first.message);
        assert!(
            !first.message.contains('['),
            "the code and source are stripped: {}",
            first.message
        );
        assert_eq!(
            first.location.as_deref(),
            Some("/*:Invoice[1]/*:LegalMonetaryTotal[1]/*:PayableAmount[1]")
        );

        assert_eq!(report.failures[1].code, "BR-CL-03");
        assert_eq!(report.failed_codes(), vec!["BR-CO-25", "BR-CL-03"]);
    }

    #[test]
    fn duplicate_codes_are_collapsed_for_reporting() {
        let twice = INVALID.replace("[BR-CL-03]", "[BR-CO-25]");
        let report = parse_report(&twice).unwrap();
        assert_eq!(report.failures.len(), 2);
        assert_eq!(report.failed_codes(), vec!["BR-CO-25"]);
    }

    #[test]
    fn a_report_without_a_summary_is_an_error() {
        assert_eq!(parse_report("<validation/>"), Err(ReportError::MissingSummary));
    }
}
